import Button from "@mui/material/Button";
import Stack from "@mui/material/Stack";
import {styled} from '@mui/material/styles'

const BootstrapButton = styled(Button)({
  boxShadow: 'none',
  textTransform: 'none',
  fontSize: 16,
  color: '#061213',
  fontWeight: 'bold',
  padding: '6px 12px',
  lineHeight: 1.5,
  fontFamily: [
    'Poppins'
  ].join(','),
  '&:hover': {
    backgroundColor: '#0069d9',
    borderColor: '#0062cc',
    boxShadow: 'none',
  },
  '&:active': {
    boxShadow: 'none',
    backgroundColor: '#0062cc',
    borderColor: '#005cbf',
  },
  '&:focus': {
    boxShadow: '0 0 0 0.2rem rgba(0,123,255,.5)',
  },
});



export default function QuackNet() {
  return (
    <Stack direction="row" spacing={1} sx= {{ justifyContent: "space-evenly", alignItems: "flex-start" }}>
      <img src={'/images/duck.png'} className="App-logo" alt="logo" />
      <Button variant="text">QuackNet</Button>
    </Stack>
  );
}
